-- Drop redundant indexes where a @unique constraint already exists on the column.
-- These indexes are superseded by the unique constraint index generated by Prisma.

DROP INDEX IF EXISTS "IcdCode_code_idx";
DROP INDEX IF EXISTS "CptCode_code_idx";
DROP INDEX IF EXISTS "SignatureUploadToken_token_idx";
DROP INDEX IF EXISTS "NotificationPreferences_userId_idx";

-- Add composite indexes for common query patterns.

CREATE INDEX "AppointmentReminder_appointmentId_status_idx" ON "AppointmentReminder"("appointmentId", "status");
CREATE INDEX "LabTestOrder_patientId_clinicId_status_idx" ON "LabTestOrder"("patientId", "clinicId", "status");
